"""Inventory tracked/current own code without treating generated bytes as source."""

from __future__ import annotations

import csv
import hashlib
import subprocess
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
CODE_SUFFIXES = frozenset({'.py', '.ts', '.tsx', '.js', '.mjs', '.css', '.sh', '.html'})
GENERATED_ROOTS = ('mathmongo/advanced_reader/static/', 'frontend/advanced-reader/dist/',
                   'frontend/advanced-reader/generated/', 'quarto_book_build/', 'quarto_book/_book/')
DEPENDENCY_PARTS = frozenset({'node_modules', 'mathdbmongo', '.venv', 'venv', 'env', 'lib'})


def category(path: str) -> tuple[str, str]:
    """Classify provenance before size; a historical generated header is not enough."""
    item = Path(path)
    if set(item.parts) & DEPENDENCY_PARTS:
        return 'dependency', 'external/runtime environment; inspect manifests and source dependencies'
    if path.startswith(GENERATED_ROOTS) or item.suffix == '.tsbuildinfo':
        return 'generated', 'review build inputs; do not refactor generated output'
    if path.startswith(('evidence/', '.scannerwork/')):
        return 'evidence', 'execution artifact; preserve historical evidence'
    if 'tests' in item.parts or 'e2e' in item.parts or item.name.startswith('test_'):
        return 'test', 'behavior verification; retained in test scope'
    if item.suffix in CODE_SUFFIXES:
        return 'maintained', 'hand-maintained source; review independently of coverage'
    if item.name in {'Makefile', 'Dockerfile', '.gitignore', '.coveragerc'} or item.suffix in {'.toml', '.yaml', '.yml', '.ini', '.properties'}:
        return 'configuration', 'validate with its build/runtime tooling'
    if item.suffix in {'.md', '.rst', '.txt'}:
        return 'documentation', 'documentation or license; not executable source'
    return 'resource', 'data/template/asset; inspect its consumers and provenance'


def inventory(root: Path) -> list[dict]:
    """Read only Git-known files, including current additions; omit deleted paths."""
    names = set()
    for arguments in (['ls-files', '-z'], ['ls-files', '--others', '--exclude-standard', '-z']):
        output = subprocess.check_output(['git', *arguments], cwd=root)
        names.update(part.decode() for part in output.split(b'\0') if part)
    rows = []
    for name in sorted(names):
        path = root / name
        if not path.is_file() or path.is_symlink():
            continue
        content = path.read_bytes()
        kind, reason = category(name)
        try:
            physical_lines: int | str = len(content.decode('utf-8').splitlines())
        except UnicodeDecodeError:
            physical_lines = ''
        rows.append({'path': name, 'lines': physical_lines, 'kind': kind, 'bytes': len(content),
                     'sha256': hashlib.sha256(content).hexdigest(), 'classification_reason': reason})
    return sorted(rows, key=lambda row: (-int(row['lines'] or 0), row['path']))


def main() -> None:
    """Write one explicit CSV to stdout; never modify sources or user data."""
    import sys

    writer = csv.DictWriter(sys.stdout, fieldnames=['path', 'lines', 'kind', 'bytes', 'sha256', 'classification_reason'])
    writer.writeheader()
    writer.writerows(inventory(ROOT))


if __name__ == '__main__':
    main()
